CREATE TABLE IF NOT EXISTS market_intelligence.public_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug varchar(120) NOT NULL UNIQUE, name varchar(200) NOT NULL, category varchar(30) NOT NULL, region varchar(200) NOT NULL, province varchar(60) NULL, agencies text NULL, summary text NOT NULL, cost_pkr_bn numeric(12,2) NULL, original_target date NULL, keywords text[] NOT NULL DEFAULT '{}', source_url text NOT NULL, source_kind varchar(10) NOT NULL DEFAULT 'OFFICIAL', is_active boolean NOT NULL DEFAULT true, record_type varchar(10) NOT NULL DEFAULT 'FACT', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS market_intelligence.project_status_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES market_intelligence.public_projects(id), status varchar(30) NOT NULL, target_date date NULL, note text NULL, event_date date NOT NULL, source_url text NOT NULL, source_kind varchar(10) NOT NULL DEFAULT 'MEDIA', record_type varchar(10) NOT NULL DEFAULT 'FACT', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (project_id, event_date, status));
CREATE TABLE IF NOT EXISTS market_intelligence.news_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outlet varchar(10) NOT NULL, title text NOT NULL, url text NOT NULL UNIQUE, published_at timestamptz NULL, topics text[] NOT NULL DEFAULT '{}', project_ids uuid[] NOT NULL DEFAULT '{}', record_type varchar(10) NOT NULL DEFAULT 'FACT', fetched_at timestamptz NOT NULL DEFAULT now())
